js = '''<script>
var SB=''' + json.dumps(sb_data, ensure_ascii=False) + ''';
var MS=''' + json.dumps(ms_data, ensure_ascii=False) + ''';
var sbMode='name', gMode='f';
function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;');}
function tpl(t,w,text){return '<div class="tpl"><div class="tpl-h"><div><div class="tpl-t">'+t+'</div>'+(w?'<div class="tpl-w">'+w+'</div>':'')+'</div><button class="copy">Копировать</button></div><div class="tpl-text">'+esc(text)+'</div></div>';}
function renderSB(){var el=document.getElementById('sb');if(!el)return;el.innerHTML=SB.map(function(s){var text=(sbMode==='name'?'[Имя клиента], добрый день! ':'Добрый день! ')+s.x;return tpl(s.t,s.w,text);}).join('');}
function renderMS(){var el=document.getElementById('ms');if(!el)return;el.innerHTML=MS.map(function(g){return '<h3>'+g.t+'</h3><div class="step-d" style="margin-bottom:8px">'+g.n+'</div>'+g.items.map(function(i){return tpl(i.t,'',bt(i[gMode]));}).join('');}).join('');}
function sw(id,cb){document.querySelectorAll('#'+id+' button').forEach(function(b){b.onclick=function(){document.querySelectorAll('#'+id+' button').forEach(function(x){x.classList.remove('on')});b.classList.add('on');cb(b.getAttribute('data-v'));};});}
document.addEventListener('DOMContentLoaded',function(){
  renderSB();renderMS();
  if(document.getElementById('sb-sw'))sw('sb-sw',function(v){sbMode=v;renderSB();});
  if(document.getElementById('g-sw'))sw('g-sw',function(v){gMode=v;renderMS();});
  document.addEventListener('click',function(e){var b=e.target.closest('.copy');if(!b)return;copyText(b,b.closest('.tpl').querySelector('.tpl-text').textContent);});
});
</script>'''

